INSERT INTO public.knowledge_chunks
  (source_id, chunk_index, title, content, locator, token_count)
VALUES
  ('biofold-evidence-levels-v1', '0', 'Scientific evidence levels in BioFold — Scientific evidence levels in BioFold', 'BioFold separates statements by how they were produced. This distinction must remain visible in the laboratory, persisted project events, citations, and assistant responses.', 'Scientific evidence levels in BioFold', '23'),
  ('biofold-evidence-levels-v1', '1', 'Scientific evidence levels in BioFold — Observed', 'Observed information comes directly from the loaded structural record: atomic coordinates, chain identifiers, residue identifiers, atom names, ligands, and waters. Observed does not mean that every biological interpretation is proven; it means BioFold read the value from the selected structure.', 'Observed', '40'),
  ('biofold-evidence-levels-v1', '2', 'Scientific evidence levels in BioFold — Calculated', 'Calculated information is derived deterministically from observed coordinates or viewer state. Examples include Euclidean atom-to-atom distance, residue counts, neighbors inside a fixed radius, and the representation currently applied. Calculated values should identify their units and input references.', 'Calculated', '37'),
  ('biofold-evidence-levels-v1', '3', 'Scientific evidence levels in BioFold — Heuristic', 'Heuristic information is a qualitative comparison intended to guide exploration. BioFold''s mutation context compares coarse charge, size, and hydrophobicity categories and identifies spatial neighbors in the static structure. It does not predict stability, folding, binding affinity, pathogenicity, or clinical effect.', 'Heuristic', '40'),
  ('biofold-evidence-levels-v1', '4', 'Scientific evidence levels in BioFold — Unavailable', 'Unavailable indicates that BioFold could not obtain or verify the requested evidence. The assistant must say what is missing and must not replace the missing result with an invented scientific claim.', 'Unavailable', '31'),
  ('biofold-structure-interpretation-v1', '0', 'Interpreting molecular structure context — Interpreting molecular structure context', 'A molecular structure is a model of coordinates under specific experimental or computational conditions. BioFold uses the selected PDB entry as the coordinate source and should identify that entry in every structure-specific explanation.
